-- ============================================
-- LUMA — Thème 13 : 3e scénario COURT x4 — Poser une question après une conférence
-- ============================================


update scenarios set content = '{"characters": {"speaker": "l''intervenant", "moderator": "le modérateur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "speaker", "text": "That concludes my talk. I''d love to take a few questions now, if there''s time.", "text_fr": "Cela conclut ma présentation. J''aimerais prendre quelques questions maintenant, s''il y a le temps.", "choices": [{"text": "(Raise your hand confidently.)", "text_fr": "(Lève la main avec assurance.)", "next": "n2"}, {"text": "(Hesitate for a moment, then raise your hand anyway.)", "text_fr": "(Hésite un moment, puis lève quand même la main.)", "next": "n2b"}]}, "n2": {"speaker": "moderator", "text": "Yes, you in the third row, go ahead.", "text_fr": "Oui, vous au troisième rang, allez-y.", "choices": [{"text": "Thank you — you mentioned scaling challenges. Could you elaborate on the biggest one you faced?", "text_fr": "Merci — vous avez mentionné des défis de mise à l''échelle. Vous pourriez développer sur le plus grand que vous avez rencontré ?", "next": "n3"}, {"text": "Great talk. How do you see this trend evolving over the next five years?", "text_fr": "Super présentation. Comment voyez-vous cette tendance évoluer dans les cinq prochaines années ?", "next": "n3"}]}, "n2b": {"speaker": "moderator", "text": "Go ahead, don''t be shy!", "text_fr": "Allez-y, soyez pas timide !", "choices": [{"text": "Thank you — I was curious about the biggest challenge you faced scaling this.", "text_fr": "Merci — j''étais curieux du plus grand défi que vous avez rencontré en mettant ça à l''échelle.", "next": "n3"}]}, "n3": {"speaker": "speaker", "text": "Great question! Honestly, the hardest part was maintaining quality while growing fast.", "text_fr": "Excellente question ! Honnêtement, la partie la plus dure était de maintenir la qualité tout en grandissant vite.", "choices": [{"text": "That resonates a lot with challenges in my own field, thank you for sharing.", "text_fr": "Ça résonne beaucoup avec les défis dans mon propre domaine, merci d''avoir partagé.", "next": "n4"}]}, "n4": {"speaker": "speaker", "text": "Thanks for the thoughtful question — it''s exactly the kind of challenge worth discussing.", "text_fr": "Merci pour la question réfléchie — c''est exactement le genre de défi qui mérite d''être discuté.", "choices": [{"text": "(Sit back down, feeling good about engaging with the speaker.)", "text_fr": "(Se rassoit, se sentant bien d''avoir échangé avec l''intervenant.)", "next": "end_asked"}]}, "end_asked": {"speaker": "moderator", "text": "Great question to close on. Thank you all for attending today''s session!", "text_fr": "Excellente question pour conclure. Merci à tous d''avoir assisté à la session d''aujourd''hui !", "end": true, "ending_label": "Question pertinente posée avec assurance 🎤✅"}}}'::jsonb, is_playable = true
where title = 'Poser une question après une conférence'
  and theme_id = (select id from scenario_themes where position = 13 and language_id = (select id from languages where code = 'en'));
